export const escapeHTML=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function parseRequest(query,mode='live'){const q=query.toLowerCase();const city=CITIES.find(c=>c.aliases.some(a=>q.includes(a)));let type=/hospital|clinic|अस्पताल|चिकित्सालय/.test(q)?'hospital':/school|विद्यालय|स्कूल/.test(q)?'school':null;if(mode==='upload')return {city:city||null,type,engine:'Rules',query};if(!city||!type)throw Error('Please name schools or hospitals and one supported city: '+CITIES.map(c=>c.name).join(', ')+'. Hindi names work too.');return {city,type,engine:'Rules',query};}
export const normalize=s=>String(s??'').normalize('NFKC').toLowerCase().replace(/\b(govt|government)\b/g,'government').replace(/\bst\.?\s/g,'saint ').replace(/[^\p{L}\p{N}\s]/gu,' ').replace(/\s+/g,' ').trim();
function similarity(a,b){const aa=new Set(normalize(a).split(' ').filter(Boolean)),bb=new Set(normalize(b).split(' ').filter(Boolean));return [...aa].filter(x=>bb.has(x)).length/Math.max(aa.size,bb.size,1);}
const phone=s=>String(s||'').replace(/\D/g,'').slice(-10);
export function relation(a,b){const ns=similarity(a.name,b.name);const sameId=a.entityId&&b.entityId&&a.entityId===b.entityId;const hasConflictId=a.entityId&&b.entityId&&a.entityId!==b.entityId;if(hasConflictId)return ns>.55?{kind:'separate',reason:'Different explicit entity identifiers. Kept separate even though the names are similar.'}:null;if(sameId)return {kind:'merge',reason:'The same explicit identifier appears in both records.'};const sameAddress=a.address&&b.address&&normalize(a.address)===normalize(b.address);const samePhone=phone(a.phone).length>=8&&phone(a.phone)===phone(b.phone);if((ns>=.4&&sameAddress)||(ns>=.6&&samePhone)||ns>=.75)return {kind:'possible',reason:sameAddress?'Similar names and the same normalized address. Identity still needs your review.':samePhone?'Similar names and matching phone digits. Shared switchboards are possible; review required.':'Similar name tokens. Names alone cannot establish identity.'};return null;}
export function buildGroups(raw,decisions={}){const parents=raw.map((_,i)=>i);const root=i=>parents[i]===i?i:(parents[i]=root(parents[i]));const join=(i,j)=>{const ri=root(i),rj=root(j);if(ri===rj)return true;const left=raw.map((_,k)=>k).filter(k=>root(k)===ri),right=raw.map((_,k)=>k).filter(k=>root(k)===rj);for(const a of left)for(const b of right)if(decisions[[raw[a].id,raw[b].id].sort().join('::')]==='separate')return false;parents[rj]=ri;return true};const pairs=[];const candidatePairs=[];if(raw.length<=600){for(let i=0;i<raw.length;i++)for(let j=i+1;j<raw.length;j++)candidatePairs.push([i,j]);}else{const blocks=new Map(),seen=new Set();raw.forEach((r,i)=>{const keys=[r.entityId?'id:'+r.entityId:'',r.address?'addr:'+normalize(r.address):'',...normalize(r.name).split(' ').filter(t=>t.length>3&&!['college','school','institute','university','government','public'].includes(t)).map(t=>'name:'+t)].filter(Boolean);for(const k of keys){const prior=blocks.get(k)||[];for(const j of prior.slice(0,k.startsWith('id:')?1:50)){const pair=j+':'+i;if(!seen.has(pair)){seen.add(pair);candidatePairs.push([j,i]);}}prior.push(i);blocks.set(k,prior)}});for(const key of Object.keys(decisions)){const ids=key.split('::'),i=raw.findIndex(r=>r.id===ids[0]),j=raw.findIndex(r=>r.id===ids[1]);if(i>=0&&j>=0)candidatePairs.push([i,j]);}}for(const [i,j] of candidatePairs){const key=[raw[i].id,raw[j].id].sort().join('::');const r=relation(raw[i],raw[j]);const choice=decisions[key];if(r||choice){const kind=choice==='merge'?'merge':choice==='separate'?'separate':r?.kind||'possible';const p={key,a:raw[i].id,b:raw[j].id,...r,kind,manual:!!choice};pairs.push(p);if(kind==='merge'&&!join(i,j)){p.kind='separate';p.reason='Blocked by an explicit keep-separate decision within the resulting group.';}}}const buckets=new Map();raw.forEach((r,i)=>{const key=root(i);if(!buckets.has(key))buckets.set(key,[]);buckets.get(key).push(r)});const groups=[...buckets.values()].map(records=>{const values={};for(const field of ['name','address','city','phone','entityId','category','state','district','website','management','university','email']){values[field]=[...new Set(records.map(r=>r[field]).filter(Boolean))];}const conflicts=['phone','address','city','website','state'].filter(f=>new Set(values[f].map(f==='phone'?phone:normalize)).size>1);return {id:records[0].id,name:records[0].name,city:values.city[0]||'',address:values.address[0]||'',records,values,conflicts,merged:records.length>1};});const groupOf=new Map(groups.flatMap(g=>g.records.map(r=>[r.id,g.id])));const pending=pairs.filter(p=>p.kind==='possible'&&groupOf.get(p.a)!==groupOf.get(p.b));return {groups,pairs,pending};}
export function parseCSV(text){text=text.replace(/^\uFEFF/,'');const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++;}else if(quoted||cell==='')quoted=!quoted;else cell+=c;}else if(c===','&&!quoted){row.push(cell);cell='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))rows.push(row);row=[];cell='';}else cell+=c;}if(quoted)throw Error('CSV contains an unclosed quoted field.');if(cell||row.length){row.push(cell);if(row.some(x=>x.trim()))rows.push(row);}if(rows.length<2)throw Error('CSV needs a header row and at least one data row.');const headers=rows.shift().map(h=>normalize(h).replace(/ /g,'_'));if(new Set(headers).size!==headers.length)throw Error('CSV contains duplicate column names.');return rows.map((r,i)=>{if(r.length!==headers.length)throw Error(`CSV row ${i+2} has ${r.length} columns; expected ${headers.length}.`);return Object.fromEntries(headers.map((h,j)=>[h,r[j].trim()]));});}
export function csvRows(rows,source){return rows.map((r,i)=>{const name=r.name||r.school_name||r.hospital_name||r.facility_name||r['नाम'];if(!name)throw Error(`Row ${i+2}: add a name, school_name, hospital_name or facility_name column.`);return {id:`${source}:${i}`,name,address:r.address||r['पता']||'',city:r.city||r.district||'',phone:r.phone||r.telephone||'',entityId:r.wikidata||r.udise_code&&`udise:${r.udise_code}`||r.entity_id||'',category:r.category||r.type||'',source,sourceUrl:safeURL(r.source_url),sourceRow:i+2,retrieved:new Date().toISOString(),lat:Number(r.lat)||null,lon:Number(r.lon)||null};});}
export function safeURL(s){try{const u=new URL(s);return ['https:','http:'].includes(u.protocol)?u.href:'';}catch{return '';}}
export function toCSV(groups){const headers=['name','aliases','city','addresses','phones','entity_ids','source_names','source_urls','source_rows','retrieved_at','status','conflicting_fields','state','district','websites','management','university','email'];const cell=v=>{let s=String(v??'');if(/^[\s]*[=+@-]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};return '\uFEFF'+[headers,...groups.map(g=>[g.name,g.values.name.join(' | '),g.values.city.join(' | '),g.values.address.join(' | '),g.values.phone.join(' | '),g.values.entityId.join(' | '),g.records.map(r=>r.source).join(' | '),g.records.map(r=>r.sourceUrl).filter(Boolean).join(' | '),g.records.map(r=>r.source+':'+(r.sourceRow||r.id)).join(' | '),g.records.map(r=>r.retrieved).join(' | '),g.conflicts.length?'conflict':g.merged?'merged':'single',g.conflicts.join(' | '),g.values.state.join(' | '),g.values.district.join(' | '),g.values.website.join(' | '),g.values.management.join(' | '),g.values.university.join(' | '),g.values.email.join(' | ')])].map(r=>r.map(cell).join(',')).join('\r\n');}
export function makeSample(plan){const city=plan.city?.name||'Delhi',type=plan.type||'school';const names=type==='school'?['Aravali Public School','Lotus Valley School','Greenfield Academy','Riverdale Public School','Horizon Learning Centre','Cedar Grove School','Sunrise Public School','Oakwood Academy','Bluebell School','Maple Leaf School']:['Aravali Health Centre','Lotus Community Hospital','Greenfield Clinic','Riverdale Hospital','Horizon Health Centre','Cedar Grove Clinic','Sunrise Hospital','Oakwood Medical Centre','Bluebell Clinic','Maple Health Centre'];const regions=['Malviya Nagar','Sector 4','Green Park','Central Avenue','East Block','West Enclave','Sector 7','Lake Road','North Colony','Garden Lane'];const now=new Date().toISOString();const raw=names.map((name,i)=>({id:`demo-a-${i}`,name,address:`${i+12}, ${regions[i]}`,city,phone:`011400010${String(i).padStart(2,'0')}`,entityId:i<4?`DEMO-${type.toUpperCase()}-${i+1}`:'',category:type,source:'Sample directory A',sourceUrl:'',sourceRow:i+2,retrieved:now}));[0,1,2,3].forEach(i=>raw.push({...raw[i],id:`demo-b-${i}`,name:i===0?(type==='school'?'अरावली पब्लिक स्कूल':'अरावली स्वास्थ्य केंद्र'):names[i].replace('School','Sch.').replace('Hospital','Hosp.'),source:'Sample directory B',sourceRow:i+2,phone:i===1?'01149999999':raw[i].phone}));raw.push({...raw[6],id:'demo-b-6',name:names[6]+' (Main)',source:'Sample directory B',sourceRow:7});raw.push({...raw[0],id:'demo-b-branch',entityId:'DEMO-OTHER-BRANCH',address:'88, North Extension',source:'Sample directory B',sourceRow:8});return raw;}
